'use strict';
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let role=new URLSearchParams(location.search).get('role')||'buyer', rid=new URLSearchParams(location.search).get('run')||localStorage.getItem('saunpdo-run'), tokens={}, data=null, selected=null, busy=false, signature='', unreadSeen=new Set();
let form={minutes:'30',confirmed:false,text:'',audio:'',mode:'practice'};
const labels={run_started:'Run opened',buyer_granted:'Aarav gave permission',buyer_revoked:'Aarav withdrew permission',invitation_responded:'Invitation answered',availability_changed:'Availability changed',receiver_audio_uploaded:'Voice note arrived',receiver_text_received:'Message arrived',connector_request:'API request',connector_response:'API response',model_output:'Model responded',model_tool_request:'Agent chose an action',tool_result:'Tool returned',message_stored:'Message stored in app',message_viewed:'Message shown in role view',wait_registered:'Waiting for a person',timer_expired:'Real timer expired',case_closed:'Agent ended the case',technical_halt:'Run stopped on an error',presenter_note:'Model note'};
const prettyTime=t=>new Date(t).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,5000)}
async function request(path,body,as=role){const options=body?{method:'POST',headers:{'Content-Type':'application/json','X-SaunpDo-Session':tokens[as]},body:JSON.stringify(body)}:{};const response=await fetch(path,options);const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result}
function setURL(){history.replaceState(null,'',`/?run=${encodeURIComponent(rid)}&role=${role}`);localStorage.setItem('saunpdo-run',rid)}
async function refresh(force=false){if(busy&&!force)return;try{const d=await request('/api/state'+(rid?'?run='+encodeURIComponent(rid):''));data=d;if(!rid){if(force||!signature){signature='empty';render()}return}const next=JSON.stringify([d.run,d.case,d.messages,d.events.length,d.decisions.length,role]);if(force||signature!==next){if(!force&&document.activeElement?.id==='receiver-text')return;signature=next;render();markRead()} }catch(e){toast(e.message)}}
function closed(){return data?.run&&['closed','halted'].includes(data.run.status)}
function statusText(){if(data.run.status==='running')return 'SaunpDo is working';if(data.run.status==='halted')return 'Run needs attention';if(data.run.status==='closed')return {unresolved:'Delivery remains unresolved',declined:'Receiver declined',cancelled:'Permission withdrawn'}[data.case.outcome]||'Run ended';if(data.run.status==='waiting')return 'Waiting for a person';return data.case.buyer_grant?'Ready for the next input':'Ready to begin'}
function statusTag(){return `<span class="run-tag ${data.run.status==='running'?'working':''} ${data.run.status==='closed'?'closed':''}"><i class="dot"></i>${esc(statusText())}</span>`}
const art=`<div class="parcel-art" aria-hidden="true"><svg viewBox="0 0 100 100" fill="none"><rect x="17" y="20" width="65" height="55" rx="6" fill="#d3ded5" transform="rotate(-8 17 20)"/><path d="M23 27L81 20L88 70L31 78Z" fill="#a8bdae"/><path d="M28 36L82 29M31 47L83 40M33 58L85 51M34 68L86 62" stroke="#d4dfd3" stroke-width="3"/><path d="M52 24L60 75" stroke="#f1ebdc" stroke-width="14"/><rect x="47" y="40" width="24" height="17" rx="2" transform="rotate(-8 47 40)" fill="#faf8ef"/><path d="M54 45L62 44M54 49L65 48" stroke="#9eab95"/></svg></div>`;
function orderCard(){return `<section class="card"><h2 class="card-title">One parcel <span class="micro">Demo order</span></h2><div class="order">${art}<div><div class="merchant">${esc(data.case.merchant.name)}</div><div class="item">${esc(data.case.order.description)}</div><div>₹${data.case.order.value_inr.toLocaleString('en-IN')} <span class="paid">Paid already</span></div></div></div><div class="order-meta"><span>Out for delivery · 3 Oct 2026</span><span>Scenario status</span></div></section>`}
function steps(){const s=data.case;let level=s.buyer_grant?1:0;if(s.invitation?.choice==='Accept invitation')level=2;if(s.receiver_availability||data.messages.some(m=>m.purpose==='explain'))level=3;if(s.outcome)level=4;return `<div class="steps">${['Permission','Invitation','Conversation','Outcome'].map((x,i)=>`<div class="step ${i<level?'done':i===level?'current':''}"><span>0${i+1}</span>${x}</div>`).join('')}</div>`}
function note(){return `<div class="note"><b>Your delivery company still decides release.</b><br>This demo helps the family coordinate. It cannot replace the delivery company’s verification or confirm a delivery.</div>`}
function buyer(){const s=data.case,g=s.buyer_grant;return `<div class="heading"><div><div class="eyebrow">Aarav’s view</div><h1>Someone you trust.<br>One parcel at a time.</h1><p class="lede">Let Maa know what is coming, with permission that stays in your hands.</p></div>${statusTag()}</div>${steps()}<div class="grid"><div>${orderCard()}<section class="card"><h2 class="card-title">${g?'Your permission':'Choose who can help'}</h2><div class="person"><div class="avatar">M</div><div><b>Maa <span class="micro">· Meera, demo alias</span></b><small>Adult receiver · At the demo home</small></div></div>${!g&&!closed()?`<label class="field-label" for="minutes">Permission lasts for</label><select id="minutes"><option value="15" ${form.minutes==='15'?'selected':''}>15 minutes</option><option value="30" ${form.minutes==='30'?'selected':''}>30 minutes</option><option value="60" ${form.minutes==='60'?'selected':''}>1 hour</option></select><label class="consent"><input id="confirmed" type="checkbox" ${form.confirmed?'checked':''}><span>I choose Maa for this bedsheet parcel at this home. This permission does not let her pay, change the address or arrange a return.</span></label><button class="primary wide" data-act="grant" ${!form.confirmed?'disabled':''}>Give permission for this parcel <span>↗</span></button><p class="helper">Maa still gets to choose. She can say no at any time.</p>`:`<div class="compact-info"><span>Scope</span><b>This parcel, this home</b></div><div class="compact-info"><span>Valid until</span><b>${g?esc(prettyTime(g.expires_at)):'Not granted'}</b></div><div class="compact-info"><span>Status</span><b>${g?.revoked_at?'Withdrawn':g?.expires_at<new Date().toISOString()?'Expired':closed()?'Run ended':'Permission recorded'}</b></div>${g&&!g.revoked_at&&!closed()?'<button class="danger" data-act="revoke">Withdraw permission</button>':''}<p class="helper">This records your choice in the demo. It is not carrier approval.</p>`}</section>${note()}</div><div>${inbox('buyer')}<section class="card"><h2 class="card-title">At a glance</h2><div class="compact-info"><span>Invitation</span><b>${esc(s.invitation?.choice||'Not answered')}</b></div><div class="compact-info"><span>${s.outcome==='declined'?'Earlier availability':'Availability'}</span><b>${esc(s.receiver_availability?.choice||'Not confirmed')}</b></div><div class="compact-info"><span>Delivery</span><b>Not confirmed</b></div></section></div></div>`}
function inbox(who){const recipient=data.case[who].id;const messages=data.messages.filter(m=>m.recipient===recipient);const human=who==='receiver'?data.events.filter(e=>e.actor==='receiver'&&['receiver_audio_uploaded','receiver_text_received','invitation_responded','availability_changed'].includes(e.event_type)):[];const items=[...messages.map(m=>({at:m.created,m})),...human.map(e=>({at:e.received_at,e}))].sort((a,b)=>a.at.localeCompare(b.at));return `<section class="card inbox"><h2 class="card-title">${who==='receiver'?'SaunpDo से बातचीत':'Updates from SaunpDo'} <span class="micro">In-app inbox</span></h2>${items.length?items.map(({m,e})=>m?`<div class="bubble"><div class="sender"><span>SaunpDo</span><span>${esc(prettyTime(m.created))}</span></div><p>${esc(m.text)}</p>${CHOICES_HTML(m)}<div class="answered">${m.read_at?'Shown in this role view':'Stored in app'}</div></div>`:`<div class="bubble human"><div class="sender"><span>Maa</span><span>${esc(prettyTime(e.received_at))}</span></div>${e.event_type==='receiver_audio_uploaded'?`<p>Voice note · ${e.payload.duration_seconds.toFixed(1)}s</p><audio controls preload="none" class="small-audio" src="/api/audio?id=${encodeURIComponent(e.payload.audio_id)}"></audio>`:`<p>${esc(e.payload.text||e.payload.choice)}</p>`}</div>`).join(''):`<div class="empty"><div class="empty-symbol">⌁</div><p>${who==='buyer'?'SaunpDo’s updates will appear here after you give permission.':'Aarav की मंज़ूरी के बाद निमंत्रण यहाँ आएगा।'}</p></div>`}${data.run.status==='running'?'<p class="helper"><i class="dot"></i>SaunpDo is working on the latest input…</p>':''}${data.run.status==='halted'?`<div class="note halt"><b>The run stopped.</b><br>${esc(data.run.failure)}<br>Open the run log to inspect the result.</div>`:''}${who==='receiver'&&!closed()?composer():''}</section>`}
function CHOICES_HTML(m){if(m.answered)return `<div class="answered">Your choice: ${esc(m.answered)}</div>`;const choices={invitation:['Accept invitation','Decline invitation'],availability:['I can receive','Not this parcel','I cannot receive']}[m.response_kind];if(!choices||closed())return '';return `<div class="choices">${choices.map(c=>`<button class="chip" data-response="${esc(c)}" data-message="${m.id}">${esc(c)}</button>`).join('')}</div>`}
function composer(){const samples=[...data.samples];if(form.uploaded)samples.push(form.uploaded);const picked=form.audio||samples[0]?.id||'';return `<div class="compose"><label for="receiver-text">अपना सवाल पूछें</label><textarea id="receiver-text" placeholder="पार्सल के बारे में क्या जानना चाहती हैं?">${esc(form.text)}</textarea><div class="compose-buttons"><button class="secondary" data-act="text" ${!form.text.trim()?'disabled':''}>Send message</button></div><div class="composer-divider">Or send a voice note</div><label for="audio-choice" class="micro">Choose a real recording</label><select id="audio-choice">${samples.map(a=>`<option value="${a.id}" ${a.id===picked?'selected':''}>${esc(a.name)} · ${a.duration.toFixed(1)}s</option>`).join('')}</select>${picked?`<audio controls preload="none" src="/api/audio?id=${encodeURIComponent(picked)}"></audio>`:''}<div class="compose-buttons"><button class="primary" data-act="audio" ${!picked?'disabled':''}>Send voice note ↗</button></div><label class="helper" for="upload-audio">Or upload your own recording</label><input id="upload-audio" type="file" accept=".m4a,.mp3,.wav,.aac,.ogg,.flac"><p class="helper">Audio goes to Gnani. The returned transcript goes to Gemini. Your permission choices use the buttons above.</p></div>`}
function availabilityForm(){const s=data.case;if(data.messages.some(m=>m.response_kind==='availability'&&!m.answered)||closed()||s.invitation?.choice!=='Accept invitation'||s.receiver_availability||!s.buyer_grant||s.buyer_grant.revoked_at||s.buyer_grant.expires_at<new Date().toISOString())return '';return `<p class="field-label">Will you be available for this parcel?</p><div class="choices">${['I can receive','Not this parcel','I cannot receive'].map(c=>`<button class="chip" data-availability="${c}">${c}</button>`).join('')}</div>`}
function receiver(){return `<div class="heading"><div><div class="eyebrow">Maa’s view · Meera is a demo alias</div><h1 class="hindi">आपका पार्सल,<br>आपकी मर्ज़ी।</h1><p class="lede">जानिए क्या आ रहा है। कोई सवाल हो, तो अपनी आवाज़ में पूछिए।</p></div>${statusTag()}</div>${steps()}<div class="grid"><div>${orderCard()}<section class="card"><h2 class="card-title">Your choice matters</h2><p class="status-message">Saying you are available does not mean you must accept the parcel.</p>${availabilityForm()}${data.case.receiver_availability?.choice==='I can receive'&&!closed()?'<button class="danger" data-act="withdraw">I cannot receive</button>':'<p class="helper">You can refuse, even after saying you are available.</p>'}</section>${note()}</div><div>${inbox('receiver')}</div></div>`}
function eventSummary(e){const p=e.payload;if(p.text)return p.text.slice(0,150);if(p.name)return p.name+(p.arguments?.reason?' · '+p.arguments.reason:'');if(p.provider)return p.provider+(p.status_code?' · HTTP '+p.status_code:'');if(p.tool_name)return p.tool_name+(p.response?.error?' · '+p.response.error.code:'');if(p.choice)return p.choice;if(p.outcome)return p.outcome;if(p.filename)return p.filename;return p.message||p.reason_code||''}
function presenter(){const events=data.events;if(!selected)selected=events.at(-1)?.event_id;const current=events.find(e=>e.event_id===selected)||events.at(-1);const api=events.filter(e=>e.event_type==='connector_response');return `<div class="heading"><div><div class="eyebrow">The observable run</div><h1>Every choice.<br>Every source.</h1><p class="lede">See what arrived, what SaunpDo chose, and what actually came back.</p></div>${statusTag()}</div><div class="toolbar"><select id="run-picker" aria-label="Choose saved run">${data.runs.map(r=>`<option value="${r.id}" ${r.id===rid?'selected':''}>${prettyTime(r.created)} · ${r.mode} · ${r.status}</option>`).join('')}</select><a class="secondary" href="/api/export?run=${encodeURIComponent(rid)}">Export this run ↓</a><div class="new-run-box"><select id="run-mode" aria-label="New run mode"><option value="practice" ${form.mode==='practice'?'selected':''}>Practice clicks</option><option value="participant" ${form.mode==='participant'?'selected':''}>Participant demo</option></select><button class="secondary" data-act="new-run">New run +</button></div></div><div class="notice">${data.run.mode==='practice'?'Practice actions are labelled OPERATOR_TEST_ACTION. They are not participant consent.':'Participant mode records actual choices through these demo role controls. This is not production identity verification.'} The order is fictional. Proposed carrier features are disabled.</div><div class="metrics"><div class="metric"><b>${data.decisions.length}</b><span>Model choices</span></div><div class="metric"><b>${api.length}</b><span>Actual API responses</span></div><div class="metric"><b>${data.messages.length}</b><span>Messages stored in app</span></div><div class="metric"><b>0</b><span>Carrier release decisions</span></div></div><div class="evidence-grid"><div class="timeline">${events.slice().reverse().map(e=>`<button class="event ${e.event_id===current?.event_id?'selected':''}" data-event="${e.event_id}"><div class="line"><span class="event-title">${esc(labels[e.event_type]||e.event_type)}</span><span class="time">${prettyTime(e.received_at)}</span></div><div class="summary">${esc(eventSummary(e))}</div><span class="tag ${e.source_mode==='LIVE_API'?'real':e.source_mode.includes('TEST')?'test':''}">${esc(e.actor)} · ${esc(e.source_mode)}</span></button>`).join('')}</div><section class="card inspect" id="inspect">${inspect(current)}</section></div>`}
function inspect(e){if(!e)return '<p class="muted">Waiting for the first event.</p>';const p=e.payload;let paths=[];if(p.body?.path)paths.push(['Full request body',p.body.path]);if(p.response_body?.path)paths.push(['Full response body',p.response_body.path]);if(p.response_ref?.path)paths.push(['Model response',p.response_ref.path]);if(p.body?.path){const meta=p.body.path.replace(/-request\.body$/,'-request.json');if(meta!==p.body.path)paths.push(['Request metadata',meta])}return `<h2 class="card-title">${esc(labels[e.event_type]||e.event_type)}</h2><div class="micro">${esc(e.event_id)} · ${esc(prettyTime(e.received_at))}</div>${p.arguments?.reason?`<p class="decision-reason"><b>${esc(p.arguments.rule_id)}</b> · ${esc(p.arguments.reason)}</p>`:''}${paths.length?`<div class="toolbar">${paths.map(([label,path])=>`<button class="secondary" data-artifact="${esc(path)}">${label}</button>`).join('')}</div>`:''}<pre id="detail-json">${esc(JSON.stringify(e,null,2))}</pre>`}
function render(){document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===role));if(!rid||!data.run){$('#app').innerHTML='<div class="heading"><div><div class="eyebrow">SaunpDo · Working demo</div><h1>A familiar hand<br>at home.</h1><p class="lede">Start a practice run to explore the buyer, receiver and agent views.</p></div></div><button class="primary" data-act="new-run">Start a practice run ↗</button>';return}$('#mode-note').textContent=data.run.mode==='practice'?'Practice clicks · Not participant consent':'Participant demo · Demo role controls';$('#app').innerHTML=role==='presenter'?presenter():role==='receiver'?receiver():buyer()}
async function markRead(){if(!['buyer','receiver'].includes(role))return;for(const m of data.messages.filter(m=>m.recipient===data.case[role].id&&!m.read_at)){if(unreadSeen.has(m.id))continue;unreadSeen.add(m.id);request('/api/read',{run_id:rid,message_id:m.id},role).catch(()=>unreadSeen.delete(m.id))}}
async function act(kind,args){const version=data.case.state_version;await request('/api/action',{run_id:rid,kind,args,expected_state_version:version,request_id:crypto.randomUUID()});await refresh(true)}
document.addEventListener('input',e=>{if(e.target.id==='receiver-text'){form.text=e.target.value;const b=document.querySelector('[data-act=text]');if(b)b.disabled=!form.text.trim()}if(e.target.id==='confirmed'){form.confirmed=e.target.checked;const b=document.querySelector('[data-act=grant]');if(b)b.disabled=!form.confirmed}});
document.addEventListener('change',async e=>{try{if(e.target.id==='minutes')form.minutes=e.target.value;if(e.target.id==='audio-choice'){form.audio=e.target.value;render()}if(e.target.id==='run-mode')form.mode=e.target.value;if(e.target.id==='run-picker'){rid=e.target.value;selected=null;setURL();await refresh(true)}if(e.target.id==='upload-audio'){const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Use a recording under 20 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const a=await request('/api/upload',{run_id:rid,name:file.name,data:btoa(raw)},'receiver');form.uploaded={id:a.audio_id,name:a.name,duration:a.duration};form.audio=a.audio_id;render();toast('Recording ready. Press Send voice note to submit it.')}}catch(err){toast(err.message)}});
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;try{if(button.dataset.role){role=button.dataset.role;selected=null;setURL();render();markRead();return}if(button.dataset.event){selected=button.dataset.event;render();return}if(button.dataset.artifact){const response=await fetch('/api/artifact?run='+encodeURIComponent(rid)+'&path='+encodeURIComponent(button.dataset.artifact));const text=await response.text();let shown=text;try{shown=JSON.stringify(JSON.parse(text),null,2)}catch{}$('#detail-json').textContent=shown;return}if(button.dataset.availability){busy=true;button.disabled=true;await act('availability',{choice:button.dataset.availability});return}if(button.dataset.response){busy=true;button.disabled=true;await act('respond',{message_id:button.dataset.message,choice:button.dataset.response});return}const action=button.dataset.act;if(!action)return;busy=true;button.disabled=true;if(action==='new-run'){const r=await request('/api/run',{mode:form.mode},'presenter');rid=r.run_id;selected=null;form.text='';form.confirmed=false;setURL();await refresh(true)}if(action==='grant')await act('grant',{minutes:Number(form.minutes),confirmed:form.confirmed});if(action==='revoke')await act('revoke',{});if(action==='withdraw')await act('withdraw',{});if(action==='text'){const text=form.text;await act('text',{text});form.text='';render()}if(action==='audio')await act('audio',{audio_id:form.audio||data.samples[0]?.id});}catch(err){toast(err.message);await refresh(true)}finally{busy=false;document.querySelectorAll('button').forEach(b=>{if(b.disabled&&b.dataset.act&&!['grant','text'].includes(b.dataset.act))b.disabled=false})}});
(async()=>{try{const session=await request('/api/session');tokens=session.tokens;const base=await request('/api/state');if(rid&&!base.runs.some(r=>r.id===rid))rid=null;if(!rid&&base.runs.length)rid=base.runs[0].id;await refresh(true);setInterval(()=>refresh(),1200)}catch(e){toast(e.message)}})();
